<template>
  <div
    class="row validation_time_spent_main"
    style="width: 250px; float: right"
    v-show="showTimerUI"
  >
    <div
      v-if="isValidationTimeSpentTimerEnable"
      class="secondary-c-text text-uppercase title q-ml-auto text-right"
    >
      {{ $t('time_spent') }}
    </div>
    <div ref="timerContainer" class="secondary-c-text validation_time_spent"></div>
  </div>
</template>

<script lang="ts">
import { defineComponent, ref, computed } from 'vue';
import { useFormBuilderSettingsStore, useDocumentStore } from 'src/store/main';
import { storeToRefs } from 'pinia';
import Clock from './helper.js';

export default defineComponent({
  el: '#app',
  props: {
    fieldName: {
      type: String,
      default: 'time_spent_on_validation',
    },
  },
  watch: {
    doc_loaded: {
      handler: function () {
        this.initView();
      },
    },
    doc_saving: {
      handler: function (newVal) {
        if (newVal === true) {
          this.stopClock();
        } else if (newVal === false) {
          // Resume timer after save completes
          this.startClock();
        }
      },
    },
  },
  mounted() {
    this.initView();
  },
  unmounted() {
    try {
      if (this.clock && this.clock.timeinterval) {
        cancelAnimationFrame(this.clock.timeinterval);
      }
    } catch (err) {}
  },
  methods: {
    initView() {
      this.makeCounter();
      this.startClock();
    },

    // Check if time tracking should be active (always when doc is loaded)
    isTrackingEnabled() {
      if (!this.doc_loaded) {
        return false;
      }
      if (!this.record || !this.record.hasOwnProperty('doc_id')) {
        return false;
      }
      return true;
    },

    getParentDivEl() {
      // Use Vue ref instead of global querySelector
      if (this.timer_parent_DIV) {
        return true;
      }

      // Access the ref from $refs
      const container = this.$refs.timerContainer as HTMLDivElement;
      if (!container) {
        return false;
      }
      this.timer_parent_DIV = container;
      return true;
    },

    makeCounter(start_timer = false) {
      try {
        // Create clock even if DOM element not available (for background tracking)
        this.clock = new Clock(
          new Date().toISOString(),
          start_timer,
          this.getTimeDiffInSeconds(),
          this.timeUpdated,
        );
        this.clock_set = true;

        // Append to DOM only if element is available
        if (this.getParentDivEl()) {
          this.timer_parent_DIV.innerHTML = '';
          this.timer_parent_DIV.appendChild(this.clock.el);
        }
      } catch (err) {
        logError(err);
      }
    },

    getTimeDiffInSeconds() {
      let timeSpent = 0;
      if (this.record && this.record.hasOwnProperty(this.fieldName)) {
        timeSpent = Number(this.record[this.fieldName]);
      }
      return timeSpent;
    },

    startClock() {
      if (!this.isTrackingEnabled() || !this.clock || this.clock.start_clock) {
        return;
      }
      this.clock.startClock(
        new Date().toISOString(),
        this.getTimeDiffInSeconds(),
      );
    },

    stopClock() {
      if (!this.isTrackingEnabled() || !this.clock || !this.clock.start_clock) {
        return;
      }
      this.clock.stopClock();
    },

    timeUpdated(t: any) {
      if (t['Total'] < 0) {
        return;
      }
      const seconds = Math.round(t['Total'] / 1000);
      this.record[this.fieldName] = seconds;
    },
  },
  setup() {
    const form_builder_settings_store = useFormBuilderSettingsStore();
    const { isValidationTimeSpentTimerEnable } = storeToRefs(
      form_builder_settings_store,
    );
    const doc_store = useDocumentStore();
    const { record, doc_loaded, saving: doc_saving } = storeToRefs(doc_store);

    // Show timer UI only when setting is enabled
    const showTimerUI = computed(() => isValidationTimeSpentTimerEnable.value);

    return {
      doc_saving,
      isValidationTimeSpentTimerEnable,
      showTimerUI,
      counter_dateTime: ref({} as Date),
      doc_loaded,
      record,
      time_spent: ref(0),
      clock: ref(),
      timer_parent_DIV: ref(),
      clock_set: ref(false),
    };
  },
});
</script>

