function CountdownTracker(label, value) {
  var el = document.createElement('span');

  el.className = 'flip-clock__piece';

  el.innerHTML =
    '<b class="flip-clock__card card"><b class="card__top"></b><b class="card__bottom"></b><b class="card__back"><b class="card__bottom"></b></b></b>';
  // el.innerHTML += '<span class="flip-clock__dot">:</span>';
  //hide text el.innerHTML += '<span class="flip-clock__slot">' + label + '</span>';

  this.el = el;

  var top = el.querySelector('.card__top'),
    bottom = el.querySelector('.card__bottom'),
    back = el.querySelector('.card__back'),
    backBottom = el.querySelector('.card__back .card__bottom');

  this.update = function (val) {
    val = ('0' + val).slice(-2);

    if (val === this.currentValue) {
      return;
    }
    // if (this.currentValue > val && val === '00') {
    //   return;
    // }

    if (this.currentValue >= 0) {
      back.setAttribute('data-value', this.currentValue);
      bottom.setAttribute('data-value', this.currentValue);
    }
    this.currentValue = val;
    top.innerText = this.currentValue;
    backBottom.setAttribute('data-value', this.currentValue);

    this.el.classList.remove('flip');
    void this.el.offsetWidth;
    this.el.classList.add('flip');
  };

  this.update(value);
}

// Calculation adapted from https://www.sitepoint.com/build-javascript-countdown-timer-no-dependencies/

export default class Clock {
  el = null;
  start_clock = false;
  timer = null;
  countdown = null;
  updateFn = {};
  diff = 0;
  callback = function () {
    // function is empty
  };
  timeinterval = null;
  throttle = 0;
  trackers = {};
  first_update = false;

  constructor(countdown, start_clock = false, diff = 0, callback) {
    this.diff = diff;
    this.start_clock = start_clock;
    this.timer = null;
    this.countdown = countdown ? new Date(Date.parse(countdown)) : null;
    this.first_update = true;

    if (callback) {
      this.callback = callback;
    }

    this.updateFn = countdown ? this.getTimeRemaining : {};
    this.el = document.createElement('div');
    this.el.className = 'flip-clock';

    this.trackers = {};
    var t = this.updateFn();
    var key;

    for (key in t) {
      if (t[key] < 0) {
        t[key] = 0;
      } // dont show time in minus
      if (key === 'Total' || key == 'Days') {
        continue;
      }
      if (key === 'Hours' && t[key] <= 0) {
        continue;
      }

      this.trackers[key] = new CountdownTracker(key, t[key]);
      this.el.appendChild(this.trackers[key].el);
    }

    this.updateClock();
  }

  startClock(countdown, diff) {
    this.countdown = countdown ? new Date(Date.parse(countdown)) : null;
    this.diff = diff;
    this.start_clock = true;
  }

  stopClock() {
    this.start_clock = false;
  }

  updateClock() {
    try {
      this.timeinterval = requestAnimationFrame(this.updateClock.bind(this));
      // throttle so it's not constantly updating the time.
      if (this.throttle++ % 30) {
        return;
      }
      if (!this.start_clock && !this.first_update) {
        return;
      }

      this.first_update = false;
      var t = this.updateFn();

      // stop after 10 Seconds
      // if (t.Seconds > 20) {
      //     return;
      // }

      if (t.Total < 0) {
        cancelAnimationFrame(this.timeinterval);
        for (let key in this.trackers) {
          this.trackers[key].update(0);
        }
        this.callback(t);
        return;
      }

      for (let key in this.trackers) {
        this.trackers[key].update(t[key]);
      }

      this.callback(t);
    } catch (err) {
      logError(err);
    }
  }

  getTimeRemaining() {
    let now = new Date();
    now = new Date(now.getTime() + 1000 * this.diff);
    var t = Date.parse(now) - this.countdown;
    if (t < 0) {
      t = 0;
    }
    return {
      Total: t,
      Days: Math.floor(t / (1000 * 60 * 60 * 24)),
      Hours: Math.floor((t / (1000 * 60 * 60)) % 24),
      Minutes: Math.floor((t / 1000 / 60) % 60),
      Seconds: Math.floor((t / 1000) % 60),
    };
  }
}
